CREATE TABLE publishers (email TEXT PRIMARY KEY, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK (role IN ('admin','publisher')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE deliverables (id UUID PRIMARY KEY, slug TEXT UNIQUE NOT NULL CHECK (slug ~ '^[a-z0-9-]+$'), title TEXT NOT NULL, type TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE versions (id UUID PRIMARY KEY, deliverable_id UUID NOT NULL REFERENCES deliverables(id), version TEXT NOT NULL CHECK (version ~ '^v[0-9]+(\.[0-9]+){0,2}$'), published_date DATE NOT NULL, published_at TIMESTAMPTZ NOT NULL DEFAULT now(), authors_json JSONB NOT NULL, change_summary TEXT NOT NULL, commit_url TEXT, publisher_email TEXT NOT NULL REFERENCES publishers(email), idempotency_key UUID UNIQUE NOT NULL, UNIQUE(deliverable_id,version));
CREATE TABLE assets (id UUID PRIMARY KEY, version_id UUID NOT NULL REFERENCES versions(id) ON DELETE CASCADE, object_key TEXT UNIQUE NOT NULL, relative_path TEXT NOT NULL, file_name TEXT NOT NULL, mime_type TEXT NOT NULL, size BIGINT NOT NULL CHECK (size >= 0), sha256 TEXT NOT NULL);
CREATE TABLE activity_log (id UUID PRIMARY KEY, action TEXT NOT NULL, actor_email TEXT NOT NULL REFERENCES publishers(email), metadata JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
